INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(465186, 43948, 327, '<td valign="top">She''s very cute with a good expression. I do wish we could of seen more of her face. Nice job.</td>', 'She''s very cute with a good expression. I do wish we could of seen more of her face. Nice job.', '2003-10-29 00:17:56.000000', NULL, 1),
(465189, 43917, 10170, '<td valign="top">Great use of light, portrays Grace nicely for me :)</td>', 'Great use of light, portrays Grace nicely for me :)', '2003-10-29 00:20:04.000000', NULL, 1),
(465206, 44289, 13390, '<td valign="top">Hmmm, i see bugars, not quite graceful.</td>', 'Hmmm, i see bugars, not quite graceful.', '2003-10-29 00:29:06.000000', NULL, 1),
(465210, 43670, 13390, '<td valign="top">Personally, I think you should have switched the focus on the word instead of the symbol. Also, I think it should have been cropped to where you couldn''t see the frayed edges. Other than that, the lighting is really good and I enjoy the detail, nicely done.</td>', 'Personally, I think you should have switched the focus on the word instead of the symbol. Also, I think it should have been cropped to where you couldn''t see the frayed edges. Other than that, the lighting is really good and I enjoy the detail, nicely done.', '2003-10-29 00:31:45.000000', NULL, 1),
(465214, 44310, 12734, '<td valign="top">Was this shot on CMU''s campus?</td>', 'Was this shot on CMU''s campus?', '2003-10-29 00:34:11.000000', NULL, 1),
(465215, 43899, 13390, '<td valign="top">I am really really enjoying this shot a lot. Personally, I would have croped it to fit the ROT because I''m not sure if it should be in the center or on the third/ The colors and lighting are absolutely stunning, good work.</td>', 'I am really really enjoying this shot a lot. Personally, I would have croped it to fit the ROT because I''m not sure if it should be in the center or on the third/ The colors and lighting are absolutely stunning, good work.', '2003-10-29 00:34:11.000000', NULL, 1),
(465217, 44459, 13390, '<td valign="top">Very Creative!! I love the quality of this photo, nicely done!</td>', 'Very Creative!! I love the quality of this photo, nicely done!', '2003-10-29 00:35:24.000000', NULL, 1),
(465219, 44309, 6804, '<td valign="top">Wow!   Excellent Art.  Very surreal         10 plus<br/>The colors are bright and full of life.</td>', 'Wow!   Excellent Art.  Very surreal         10 plusThe colors are bright and full of life.', '2003-10-29 00:36:14.000000', NULL, 1),
(465221, 44374, 13390, '<td valign="top">I love how you make it look like the wind is blowing, nicely done!</td>', 'I love how you make it look like the wind is blowing, nicely done!', '2003-10-29 00:37:24.000000', NULL, 1),
(465222, 43879, 13390, '<td valign="top">I like the idea, could use more focus and contrast.</td>', 'I like the idea, could use more focus and contrast.', '2003-10-29 00:38:08.000000', NULL, 1),
(465224, 44460, 13390, '<td valign="top">A little too bright for my taste, but nicely done anyways. Not sure how this entails grace though.</td>', 'A little too bright for my taste, but nicely done anyways. Not sure how this entails grace though.', '2003-10-29 00:39:28.000000', NULL, 1),
(465226, 43649, 10673, '<td valign="top">Captivating!  10</td>', 'Captivating!  10', '2003-10-29 00:40:04.000000', NULL, 1),
(465227, 43637, 13390, '<td valign="top">A little too much negative space for my liking. Cute girl though.</td>', 'A little too much negative space for my liking. Cute girl though.', '2003-10-29 00:40:12.000000', NULL, 1),
(465231, 43649, 13390, '<td valign="top">Great lighting. Nicely composed. Effective use of black and white.</td>', 'Great lighting. Nicely composed. Effective use of black and white.', '2003-10-29 00:41:16.000000', NULL, 1),
(465232, 43869, 13390, '<td valign="top">I love the vibrant colors! Very sharp and crisp! Good framing.</td>', 'I love the vibrant colors! Very sharp and crisp! Good framing.', '2003-10-29 00:42:09.000000', NULL, 1),
(465233, 44341, 13390, '<td valign="top">Nice detail. I feel though that the shadows are a bit distracting. Was this taken with flash? If so, I would suggest bringing in your own light source so you can manipulate it so that the shadow doesn''t detract from the image quality.</td>', 'Nice detail. I feel though that the shadows are a bit distracting. Was this taken with flash? If so, I would suggest bringing in your own light source so you can manipulate it so that the shadow doesn''t detract from the image quality.', '2003-10-29 00:44:33.000000', NULL, 1),
(465235, 44275, 13390, '<td valign="top">Very cool shot/ I really enjoy the lightoing here.</td>', 'Very cool shot/ I really enjoy the lightoing here.', '2003-10-29 00:45:10.000000', NULL, 1),
(465236, 44454, 10341, '<td valign="top">Wonderful photo. Wish the light was not quite as strong on the face, but still rated high by me. Great job!</td>', 'Wonderful photo. Wish the light was not quite as strong on the face, but still rated high by me. Great job!', '2003-10-29 00:45:41.000000', NULL, 1),
(465238, 44332, 13390, '<td valign="top">A couple of comments: I feel that the building onthe right is distractive, I feel there could be a lot more focys on the statue and and cross. Also, the graininess is distracting as well. I like the angle though, nice shot.</td>', 'A couple of comments: I feel that the building onthe right is distractive, I feel there could be a lot more focys on the statue and and cross. Also, the graininess is distracting as well. I like the angle though, nice shot.', '2003-10-29 00:47:08.000000', NULL, 1),
(465240, 44307, 13390, '<td valign="top">I love the crispness of the black and white touch you gave it. Nicely done.</td>', 'I love the crispness of the black and white touch you gave it. Nicely done.', '2003-10-29 00:48:29.000000', NULL, 1),
(465242, 43758, 13390, '<td valign="top">Feels a bit too snap-shotty for my liking. Also, I think using the flash here make sit feel that way. I like the the rustic feel to the statue though.</td>', 'Feels a bit too snap-shotty for my liking. Also, I think using the flash here make sit feel that way. I like the the rustic feel to the statue though.', '2003-10-29 00:50:30.000000', NULL, 1),
(465244, 44302, 9441, '<td valign="top">very cool colors, and such dramatic lighting!  Wonderful silhouette...nicely done.  10</td>', 'very cool colors, and such dramatic lighting!  Wonderful silhouette...nicely done.  10', '2003-10-29 00:51:51.000000', NULL, 1),
(465247, 44242, 9441, '<td valign="top">awesome lighting, so dramatic!  Cool colors and hues.</td>', 'awesome lighting, so dramatic!  Cool colors and hues.', '2003-10-29 00:53:31.000000', NULL, 1),
(465249, 44314, 6804, '<td valign="top">Great shot, the color is good. I don''t know if I like the big border yet, I think it over powers the shot a little i think. I need to come back to this one a few times through the week to settle in on a score. today its an 8</td>', 'Great shot, the color is good. I don''t know if I like the big border yet, I think it over powers the shot a little i think. I need to come back to this one a few times through the week to settle in on a score. today its an 8', '2003-10-29 00:53:46.000000', NULL, 1),
