(465277, 44455, 11855, '<td valign="top">Hey nice shot fellow Torontonian, Nice perspective of the gates. I shot something similiar for shadows but then went with another angle of the gates. Good luck!</td>', 'Hey nice shot fellow Torontonian, Nice perspective of the gates. I shot something similiar for shadows but then went with another angle of the gates. Good luck!', '2003-10-29 01:12:25.000000', NULL, 1),
(465285, 44355, 10419, '<td valign="top">Hello, fellow Torontonian :-)) Great shot. Love how close you can get to it. I know how hard it is, I\''ve tried. Really like that this is a grey scale shot. The triangular composition is nice. My only suggestion would have been to leave tiny bit more breathing space on the left of the angel. Well done.</td>', 'Hello, fellow Torontonian :-)) Great shot. Love how close you can get to it. I know how hard it is, I\''ve tried. Really like that this is a grey scale shot. The triangular composition is nice. My only suggestion would have been to leave tiny bit more breathing space on the left of the angel. Well done.', '2003-10-29 01:22:18.000000', NULL, 1),
(465290, 43809, 10848, '<td valign="top">This is outstanding! I love it, the colors are gorgeous, and the lighting is wonderful you got a 10 from me</td>', 'This is outstanding! I love it, the colors are gorgeous, and the lighting is wonderful you got a 10 from me', '2003-10-29 01:29:35.000000', NULL, 1),
(465291, 44383, 10848, '<td valign="top">This is charming, I like the concept, the teapot being suspended with the gracefullness of her hand is a good choice, I like it</td>', 'This is charming, I like the concept, the teapot being suspended with the gracefullness of her hand is a good choice, I like it', '2003-10-29 01:30:45.000000', NULL, 1),
(465293, 43794, 10848, '<td valign="top">This is precious, and the title is perfect, both are gracefu; I like the choice of choosing the black and white for this picture it seems to fit perfectly, great job</td>', 'This is precious, and the title is perfect, both are gracefu; I like the choice of choosing the black and white for this picture it seems to fit perfectly, great job', '2003-10-29 01:34:57.000000', NULL, 1),
