(465752, 44283, 6845, '<td valign="top">For me I would have liked to have seen the largest flower  almost directly in the middle, in focus. I do like the colors and flowers can certainly look graceful.</td>', 'For me I would have liked to have seen the largest flower  almost directly in the middle, in focus. I do like the colors and flowers can certainly look graceful.', '2003-10-29 11:01:35.000000', NULL, 1),
(465756, 43992, 12796, '<td valign="top">Light imbalance...!</td>', 'Light imbalance...!', '2003-10-29 11:02:48.000000', NULL, 1),
(465758, 44104, 6845, '<td valign="top">Now thats a closeup. I like the framing, and the soft focus gives it a soft almost peaceful feeling.</td>', 'Now thats a closeup. I like the framing, and the soft focus gives it a soft almost peaceful feeling.', '2003-10-29 11:03:10.000000', NULL, 1),
(465760, 43717, 6845, '<td valign="top">I like the composition and the detail.</td>', 'I like the composition and the detail.', '2003-10-29 11:04:02.000000', NULL, 1),
(465764, 44355, 6845, '<td valign="top">Good composition. I like the tones achieved through the black and white. The white sky really make the statues pop out.</td>', 'Good composition. I like the tones achieved through the black and white. The white sky really make the statues pop out.', '2003-10-29 11:05:11.000000', NULL, 1),
