(465824, 44394, 10785, '<td valign="top">Oh I so laughed when I saw this pic! This is poster material! Very well done.</td>', 'Oh I so laughed when I saw this pic! This is poster material! Very well done.', '2003-10-29 11:46:15.000000', NULL, 1),
(465825, 44224, 11155, '<td valign="top">Wonderful interpretation of the challenge.  I love the muted colors of the piano - and the stark contrast of the keys and the flower.  Nicely done.</td>', 'Wonderful interpretation of the challenge.  I love the muted colors of the piano - and the stark contrast of the keys and the flower.  Nicely done.', '2003-10-29 11:46:18.000000', NULL, 1),
(465826, 43894, 6999, '<td valign="top">I''m afraid you''re getting a 1 from me. This has a number of faults; detail is absent, the particular frozen moment you''ve chosen is ugly and actually grace-less, it appears over-compressed, or cropped from too small an orignal image, something has caused compression artefacts all over this. Then there are those white blotches, whatever they are.  Compositionally , it''s just a flag, absolutely dead centre of frame: conveys no feeling of anything much. All this is besides the issue of subject matter, and the fact that the nation this flag represents has little in my mind to do with ''Grace'' at all.</td>', 'I''m afraid you''re getting a 1 from me. This has a number of faults; detail is absent, the particular frozen moment you''ve chosen is ugly and actually grace-less, it appears over-compressed, or cropped from too small an orignal image, something has caused compression artefacts all over this. Then there are those white blotches, whatever they are.  Compositionally , it''s just a flag, absolutely dead centre of frame: conveys no feeling of anything much. All this is besides the issue of subject matter, and the fact that the nation this flag represents has little in my mind to do with ''Grace'' at all.', '2003-10-29 11:46:20.000000', NULL, 1),
(465829, 44211, 11155, '<td valign="top">I love the background.  This is a great setup, very creative.  Lighting is nice and interpretation is great.  Good luck.</td>', 'I love the background.  This is a great setup, very creative.  Lighting is nice and interpretation is great.  Good luck.', '2003-10-29 11:47:27.000000', NULL, 1),
(465831, 44459, 11155, '<td valign="top">What a shot!  I don''t like the hot spot on the shell, but everything else is so nice, I''m not counting that against you!  Nice contrast against the background.</td>', 'What a shot!  I don''t like the hot spot on the shell, but everything else is so nice, I''m not counting that against you!  Nice contrast against the background.', '2003-10-29 11:48:45.000000', NULL, 1),
