(468279, 44303, 11570, '<td valign="top">Nice long shutter speed making the milky water - not sure about the red flowers though they do distract a bit.</td>', 'Nice long shutter speed making the milky water - not sure about the red flowers though they do distract a bit.', '2003-10-31 14:07:56.000000', NULL, 1),
(468280, 44066, 11570, '<td valign="top">Nicely seen and taken IMO looks a little oversharpened to me but good all the same.</td>', 'Nicely seen and taken IMO looks a little oversharpened to me but good all the same.', '2003-10-31 14:08:43.000000', NULL, 1),
(468281, 43992, 11570, '<td valign="top">Nice portrait shot well composed and lit and gracefulness I see IMO the one area that needs a lift would be the harpist face. Perhaps a gold lastolite reflector to her left might have done it. 6</td>', 'Nice portrait shot well composed and lit and gracefulness I see IMO the one area that needs a lift would be the harpist face. Perhaps a gold lastolite reflector to her left might have done it. 6', '2003-10-31 14:11:12.000000', NULL, 1),
