(468286, 44318, 13591, '<td valign="top">Absolutely gorgeous!!  I just cant find anything wrong with this!<br/> <br/>Excellent work!  10+</td>', 'Absolutely gorgeous!!  I just cant find anything wrong with this! Excellent work!  10+', '2003-10-31 14:27:10.000000', NULL, 1),
(468291, 44318, 9821, '<td valign="top">perfect</td>', 'perfect', '2003-10-31 14:42:08.000000', NULL, 1),
(468294, 44253, 7190, '<td valign="top">Intresting shot but think it is a bit over exposed. think I know what you were going for but think it still would have been achieved by softening the lighting some.</td>', 'Intresting shot but think it is a bit over exposed. think I know what you were going for but think it still would have been achieved by softening the lighting some.', '2003-10-31 15:02:07.000000', NULL, 1),
(468348, 44460, 12674, '<td valign="top">Pretty weird...don''t see any connection with grace.</td>', 'Pretty weird...don''t see any connection with grace.', '2003-10-31 16:54:23.000000', NULL, 1),
(468358, 43758, 12674, '<td valign="top">Slightly out of focus in lower half? Also a bit of glare from flash. Great idea for grace.</td>', 'Slightly out of focus in lower half? Also a bit of glare from flash. Great idea for grace.', '2003-10-31 17:08:32.000000', NULL, 1),
(468359, 43809, 12674, '<td valign="top">OK, this flower does exude grace in its form....wonderful color, nice composition.</td>', 'OK, this flower does exude grace in its form....wonderful color, nice composition.', '2003-10-31 17:10:41.000000', NULL, 1),
(468361, 43794, 11295, '<td valign="top">Nice portrait!</td>', 'Nice portrait!', '2003-10-31 17:14:10.000000', NULL, 1),
(468362, 44394, 11295, '<td valign="top">Cute. :)</td>', 'Cute. :)', '2003-10-31 17:14:47.000000', NULL, 1),
(468363, 44360, 12674, '<td valign="top">Unusual color treatment...light areas look like they could either be frost or light gold. I like the photo but don''t get much of a grace connection.</td>', 'Unusual color treatment...light areas look like they could either be frost or light gold. I like the photo but don''t get much of a grace connection.', '2003-10-31 17:15:21.000000', NULL, 1),
(468364, 44423, 6130, '<td valign="top">I like this very much.</td>', 'I like this very much.', '2003-10-31 17:16:22.000000', NULL, 1),
(468367, 44374, 12674, '<td valign="top">Nice composition and wind effect...but not much of a connection with grace</td>', 'Nice composition and wind effect...but not much of a connection with grace', '2003-10-31 17:17:32.000000', NULL, 1),
(468369, 43996, 11295, '<td valign="top">Nice capture, but the colours are a little too extreme.. they wash one another out and detract from your focus.</td>', 'Nice capture, but the colours are a little too extreme.. they wash one another out and detract from your focus.', '2003-10-31 17:18:37.000000', NULL, 1),
