(468437, 44189, 3981, '<td valign="top">Magnificent in every detail.  This should win you a ribbon.</td>', 'Magnificent in every detail.  This should win you a ribbon.', '2003-10-31 19:06:19.000000', NULL, 1),
(468440, 43649, 3981, '<td valign="top">Awe inspiring.  A truly magnificent image.  The lonliness of the landscape - the the feeling of contriteness in this man - the hills to the far right - even the beautiful clouds - bespeak Grace.  And technically it''s close to perfect.  Congratulations!  I know this will win you a ribbon.</td>', 'Awe inspiring.  A truly magnificent image.  The lonliness of the landscape - the the feeling of contriteness in this man - the hills to the far right - even the beautiful clouds - bespeak Grace.  And technically it''s close to perfect.  Congratulations!  I know this will win you a ribbon.', '2003-10-31 19:10:48.000000', NULL, 1),
