(469368, 43795, 9437, '<td valign="top">I want to look this good when I''m her age!</td>', 'I want to look this good when I''m her age!', '2003-11-01 16:51:51.000000', NULL, 1),
(469369, 43917, 9437, '<td valign="top">Good balance in the composition.</td>', 'Good balance in the composition.', '2003-11-01 16:53:42.000000', NULL, 1),
