(469375, 44309, 9437, '<td valign="top">Don''t know how you did this but it''s fabulous!. I love the ghostly softness and the drama in the clouds. One of the few times I wish the scale went higher.</td>', 'Don''t know how you did this but it''s fabulous!. I love the ghostly softness and the drama in the clouds. One of the few times I wish the scale went higher.', '2003-11-01 17:02:01.000000', NULL, 1),
(469381, 44394, 9437, '<td valign="top">Made me laugh. Gets extra point. 9</td>', 'Made me laugh. Gets extra point. 9', '2003-11-01 17:07:23.000000', NULL, 1),
(469383, 43785, 9437, '<td valign="top">Beautiful. But then you have a great subject too. The lighting on the bridge gives it a sort of 3D look. Well done.</td>', 'Beautiful. But then you have a great subject too. The lighting on the bridge gives it a sort of 3D look. Well done.', '2003-11-01 17:11:14.000000', NULL, 1),
(469386, 44066, 9437, '<td valign="top">Great action shot. Looked at this with a 4x magnifier and didn''t see pixellation. 10</td>', 'Great action shot. Looked at this with a 4x magnifier and didn''t see pixellation. 10', '2003-11-01 17:13:12.000000', NULL, 1),
(469388, 43987, 9437, '<td valign="top">Clever still life. Unique interpretation of theme. The slightly soft focus works here.</td>', 'Clever still life. Unique interpretation of theme. The slightly soft focus works here.', '2003-11-01 17:16:39.000000', NULL, 1),
(469391, 44122, 9437, '<td valign="top">We''re getting the first snow of winter this evening. If I can get shots of it as good as this one I''ll be happy. The grass looks like it''s dancing. Well done.</td>', 'We''re getting the first snow of winter this evening. If I can get shots of it as good as this one I''ll be happy. The grass looks like it''s dancing. Well done.', '2003-11-01 17:22:25.000000', NULL, 1),
(469395, 44447, 9437, '<td valign="top">This is one of the few flat photos that I''ve ever liked. The ghostly appearence to the ship contributes to the theme.</td>', 'This is one of the few flat photos that I''ve ever liked. The ghostly appearence to the ship contributes to the theme.', '2003-11-01 17:27:37.000000', NULL, 1),
(469400, 43490, 9437, '<td valign="top">Never seen a butterfly this detailed. The color pink and the curved wings. help keep the photo on theme. 10+</td>', 'Never seen a butterfly this detailed. The color pink and the curved wings. help keep the photo on theme. 10+', '2003-11-01 17:48:41.000000', NULL, 1),
