(470113, 44330, 10739, '<td valign="top">Nice picture, nice idea. I would try to change the background, looks like a bit spooky</td>', 'Nice picture, nice idea. I would try to change the background, looks like a bit spooky', '2003-11-02 18:44:24.000000', NULL, 1),
(470114, 43785, 11817, '<td valign="top">Beautiful shot.</td>', 'Beautiful shot.', '2003-11-02 18:46:02.000000', NULL, 1),
