(470124, 44335, 11817, '<td valign="top">Nice.</td>', 'Nice.', '2003-11-02 18:53:07.000000', NULL, 1),
(470125, 43784, 10739, '<td valign="top">Great picture. Remove some noise from the highlights. The color of the shadows is really magic</td>', 'Great picture. Remove some noise from the highlights. The color of the shadows is really magic', '2003-11-02 18:53:51.000000', NULL, 1),
(470129, 44253, 10402, '<td valign="top">A unique high-key high-contrast portrait. Artistically stunning and provocative; the dark hair and eyes make an interesting contrast to the light eyebrows and lips. The white flowers add an extra something. Techncally perfect; the face is white, but not quite as white as the background so its outline is clearly visible and the nose can also be made out. Doesn''t convey grace to me as well as other images (but does meet the challenge).</td>', 'A unique high-key high-contrast portrait. Artistically stunning and provocative; the dark hair and eyes make an interesting contrast to the light eyebrows and lips. The white flowers add an extra something. Techncally perfect; the face is white, but not quite as white as the background so its outline is clearly visible and the nose can also be made out. Doesn''t convey grace to me as well as other images (but does meet the challenge).', '2003-11-02 18:56:44.000000', NULL, 1),
(470130, 44232, 11817, '<td valign="top">Good shot.</td>', 'Good shot.', '2003-11-02 18:58:15.000000', NULL, 1),
(470131, 44361, 10402, '<td valign="top">Very graceful poses. A lot of noise; it helps soften the image but the colors are a bit distracting. The background is very distracting (although I understand you didn''t have a lot of control over it).</td>', 'Very graceful poses. A lot of noise; it helps soften the image but the colors are a bit distracting. The background is very distracting (although I understand you didn''t have a lot of control over it).', '2003-11-02 19:01:26.000000', NULL, 1),
(470133, 44362, 11817, '<td valign="top">Nice.</td>', 'Nice.', '2003-11-02 19:02:49.000000', NULL, 1),
(470136, 44432, 10620, '<td valign="top">pray for me...I am no longer a member  I have been ostrasized...ginger</td>', 'pray for me...I am no longer a member  I have been ostrasized...ginger', '2003-11-02 19:06:59.000000', NULL, 1),
(470139, 44147, 10402, '<td valign="top">I''m aware of AA and from its appearance here suspect that grace is an important part of it, but I''m afraid my experience (or lack thereof) keeps me from feeling grace from this image.</td>', 'I''m aware of AA and from its appearance here suspect that grace is an important part of it, but I''m afraid my experience (or lack thereof) keeps me from feeling grace from this image.', '2003-11-02 19:12:23.000000', NULL, 1),
(470141, 44362, 10402, '<td valign="top">Beautifully captures the colors of these leaves.</td>', 'Beautifully captures the colors of these leaves.', '2003-11-02 19:13:09.000000', NULL, 1),
(470143, 43987, 1379, '<td valign="top">So.... are we the pawns?</td>', 'So.... are we the pawns?', '2003-11-02 19:15:11.000000', NULL, 1),
(470144, 43717, 10402, '<td valign="top">Great composition, exposure, and focus. The softness probably helps convey grace, but I''d still rather see it a little sharper.</td>', 'Great composition, exposure, and focus. The softness probably helps convey grace, but I''d still rather see it a little sharper.', '2003-11-02 19:16:06.000000', NULL, 1),
(470146, 43902, 10402, '<td valign="top">Nicely posed. The draped fabrics make a good setting.</td>', 'Nicely posed. The draped fabrics make a good setting.', '2003-11-02 19:17:52.000000', NULL, 1),
(470154, 44382, 10402, '<td valign="top">Great costume and pose. Nicely soft focus. Seems a little light; darkening the midtones with Levels or Curves would be helpful.</td>', 'Great costume and pose. Nicely soft focus. Seems a little light; darkening the midtones with Levels or Curves would be helpful.', '2003-11-02 19:22:45.000000', NULL, 1),
(470173, 43584, 2158, '<td valign="top">Given your title, I would say the reflection goes against what you were trying to do.</td>', 'Given your title, I would say the reflection goes against what you were trying to do.', '2003-11-02 19:42:09.000000', NULL, 1),
(470183, 44320, 3306, '<td valign="top">Nice sharp close up.</td>', 'Nice sharp close up.', '2003-11-02 20:17:26.000000', NULL, 1),
(470184, 44341, 3306, '<td valign="top">Well focused but the shadow is a little distracting.</td>', 'Well focused but the shadow is a little distracting.', '2003-11-02 20:17:58.000000', NULL, 1);
