(470365, 43737, 10402, '<td valign="top">It''s amazing that grace can be found so abundantly in a worn-out shoe. Great viewpoint, lighting, and DOF.</td>', 'It''s amazing that grace can be found so abundantly in a worn-out shoe. Great viewpoint, lighting, and DOF.', '2003-11-02 23:03:44.000000', NULL, 1),
