(474962, 43785, 12268, '<td valign="top">congrats on the win. Most deserved! I love the shadows &amp; such on the opera house &amp; really love the moon in the back ground. I''m super happy you wona ribbon!</td>', 'congrats on the win. Most deserved! I love the shadows & such on the opera house & really love the moon in the back ground. I''m super happy you wona ribbon!', '2003-11-06 01:49:50.000000', NULL, 0),
(474977, 43996, 9889, '<td valign="top">Regardless how it may have appeared to some, this photo is perfectly legal in Photoshop terms.<br/> <br/>I cropped it a lot (I usually like not to crop at all if possible) and that required some patient use of Unsharp Mask.<br/> <br/>I also, but just slightly, raised the color saturation to achieve the final result.<br/> <br/>I have out-takes but they do not show the reflections because this Blue Heron is taken by different, most normal perspectives. I will put them on-line asap including a version of the original (having being working on PhoTournament.com and re-assetting my websites, I removed my galleries and I do not have a portfolio on-line at the moment).<br/> <br/>I did choose this perspective, at shooting time, attracted by the simmetry of the two blue spots on the bird wings which are not visibile by any other angle.<br/> <br/>Finally, I would like to share a true secret about how to take reflections like that.<br/> <br/>I do not know exactly why, maybe somebody can explain it, but when it is omogenously cloudy (and that happens quite frequently here in UK), subjects reflects in the water in a very colorful and crispy way.<br/> <br/>In addition to that, I was pretty lucky that the water in this picture is dirty, therefore the bubbles which create another interesting pattern which contributes to the intended pictorial view.<br/> <br/>This is definitely one of my best three photos ever and it prints very well. I hanged it in front of my desk wall and I love it.<br/> <br/>I final word about Photoshop artworks and tricks: it is true that, theoretically, anything can be produced (or reproduced) digitally, but when you see a photo with such complex and different patterns, to produce it in Photoshop would have required one month work from an excellent artist! <br/> <br/>Conclusion: <br/>it is much much easier to take it as you wish with your camera! ;)</td>', 'Regardless how it may have appeared to some, this photo is perfectly legal in Photoshop terms. I cropped it a lot (I usually like not to crop at all if possible) and that required some patient use of Unsharp Mask. I also, but just slightly, raised the color saturation to achieve the final result. I have out-takes but they do not show the reflections because this Blue Heron is taken by different, most normal perspectives. I will put them on-line asap including a version of the original (having being working on PhoTournament.com and re-assetting my websites, I removed my galleries and I do not have a portfolio on-line at the moment). I did choose this perspective, at shooting time, attracted by the simmetry of the two blue spots on the bird wings which are not visibile by any other angle. Finally, I would like to share a true secret about how to take reflections like that. I do not know exactly why, maybe somebody can explain it, but when it is omogenously cloudy (and that happens quite frequently here in UK), subjects reflects in the water in a very colorful and crispy way. In addition to that, I was pretty lucky that the water in this picture is dirty, therefore the bubbles which create another interesting pattern which contributes to the intended pictorial view. This is definitely one of my best three photos ever and it prints very well. I hanged it in front of my desk wall and I love it. I final word about Photoshop artworks and tricks: it is true that, theoretically, anything can be produced (or reproduced) digitally, but when you see a photo with such complex and different patterns, to produce it in Photoshop would have required one month work from an excellent artist!  Conclusion: it is much much easier to take it as you wish with your camera! ;)', '2003-11-06 02:26:21.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(475151, 44211, 10739, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by ButterflySis:</b></div><hr/><i>Ugh.  Another disappointing finish.  I gave this a 9.  I realize it''s a figurine and people consider them cliche, but give me a break!  It''s nicely set up and a beautiful image.</i></td></tr></table> <br/> <br/>Thank you for your comment, I don''t know if it''s a cliche, I would have liked some negative comment. A cliche is supposed to be a swan and it won the challenge (before DQ)... never mind.</td>', 'Originally posted by ButterflySis:Ugh.  Another disappointing finish.  I gave this a 9.  I realize it''s a figurine and people consider them cliche, but give me a break!  It''s nicely set up and a beautiful image.  Thank you for your comment, I don''t know if it''s a cliche, I would have liked some negative comment. A cliche is supposed to be a swan and it won the challenge (before DQ)... never mind.', '2003-11-06 09:51:54.000000', NULL, 0),
