(475374, 44318, 8860, '<td valign="top">Great shot which perfectly captures the theme, tranquility abd poetic beauty of the scene. Lovely lighting and composition.</td>', 'Great shot which perfectly captures the theme, tranquility abd poetic beauty of the scene. Lovely lighting and composition.', '2003-11-06 11:40:46.000000', NULL, 0),
(475698, 44318, 11184, '<td valign="top">Wow that is lovely.  Looks like it could be a scene right out of Lord of the Rings.  More than just another autumn shot and some leaves...it sets a tone and mood ready to tell a story.</td>', 'Wow that is lovely.  Looks like it could be a scene right out of Lord of the Rings.  More than just another autumn shot and some leaves...it sets a tone and mood ready to tell a story.', '2003-11-06 16:56:12.000000', NULL, 0),
(475707, 43785, 11184, '<td valign="top">Its so unfair...nothing looks that cool where the rest of us live. ;) Wonderful shot!  Would make for an exquisite print as well I am sure.</td>', 'Its so unfair...nothing looks that cool where the rest of us live. ;) Wonderful shot!  Would make for an exquisite print as well I am sure.', '2003-11-06 17:01:03.000000', NULL, 0),
(475721, 43649, 4272, '<td valign="top">Excellent!!</td>', 'Excellent!!', '2003-11-06 17:07:39.000000', NULL, 0),
